// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

/** The documents for the inspection, in the order of the category's chapters, the self-assessment first. */
export interface InspectionPackOut {
  category: "Clinic" | "IIC" | "IIB" | "IIA" | "I";
  category_label: string;
  date_from: string;
  date_to: string;
  /** The user's preference (PUT /settings/me pdf_download): Separate = show a download button per document (pdf_url); Combined = show one button for combined_export_url. Never a ZIP */
  download_mode: "Separate" | "Combined";
  /** POST here (with this answer's category, date_from, date_to) to build the combined PDF in the background */
  combined_export_url: string;
  documents: PackDocumentOut[];
  /** Documents this user may not open (left out of the combined PDF) */
  not_allowed: number;
}

export interface PackDocumentOut {
  key: string;
  title: string;
  kind: "Policy" | "Register" | "Report";
  /** True: printed for the pack's period; false: as of today */
  period: boolean;
  about: string;
  /** The indicators of the category it evidences */
  indicators: number[];
  /** False: this user lacks the permission of the document's own endpoint; show it greyed with required_permissions */
  allowed: boolean;
  /** Any one of them opens it (empty: any signed-in user) */
  required_permissions: string[];
  state: "Ready" | "Attention" | "NotReady";
  detail: string;
  /** One click, one PDF (download mode Separate) */
  pdf_url: string;
}

/** The combined inspection pack to build in the background (audit F-24): the same scope as GET /msds/inspection-pack. */
export interface PackExportIn {
  /** Clinic, IIC, IIB, IIA or I; default: the establishment's recorded category (MSDS_CATEGORY_NOT_CONFIRMED until one is recorded) */
  category?: "Clinic" | "IIC" | "IIB" | "IIA" | "I" | null;
  /** The period of the registers and reports; default: 90 days before date_to */
  date_from?: string | null;
  /** Default: today; the period is at most 366 days */
  date_to?: string | null;
}

/** The combined inspection pack built in the background (audit F-24): Queued, then Ready (download_url) or Failed. */
export interface MsdsPackExportOut {
  export_id: number;
  category: "Clinic" | "IIC" | "IIB" | "IIA" | "I";
  date_from: string;
  date_to: string;
  status: "Queued" | "Ready" | "Failed";
  filename: string | null;
  size_bytes: number | null;
  error: string | null;
  requested_at: string;
  finished_at: string | null;
  /** /api/v1/msds/inspection-pack/exports/{export_id}/pdf once Ready */
  download_url: string | null;
}

/** The establishment's PHC category as recorded, and what the beds suggest today. */
export interface MsdsProfileOut {
  /** Null until a person records it */
  category: "Clinic" | "IIC" | "IIB" | "IIA" | "I" | null;
  category_label: string | null;
  /** The PHC registration or licence number on every printout */
  registration_number: string | null;
  licence_document: LicenceDocumentOut | null;
  /** The date the category took effect on the licence */
  effective_from: string | null;
  confirmed_at: string | null;
  confirmed_by_name: string | null;
  /** Why the confirmed category differs from the suggestion, when it does */
  reason: string | null;
  /** The beds counted when it was confirmed */
  bed_count: number | null;
  /** The beds the licence names, as entered with the profile; null when none was entered */
  licensed_beds: number | null;
  /** What to look at again: more beds set up than the licence names, a licence outside its category's band. Advice only: the category stays as recorded */
  review: string[];
  suggestion: CategorySuggestionOut;
  /** True when nothing is recorded, or the beds now suggest another band than when it was recorded: offer the admin the facility settings */
  needs_confirmation: boolean;
  /** The PHC frameworks Haspataal holds: Clinic, II C, II B, II A, I */
  standards: StandardOut[];
}

/** The PHC licence in the compliance register, or the entry that renewed it since. */
export interface LicenceDocumentOut {
  document_id: number;
  title: string;
  authority: string | null;
  reference_no: string | null;
  valid_until: string | null;
  state: "Valid" | "DueForRenewal" | "Expired" | "NoExpiry" | "Renewed" | "Withdrawn";
  has_scan: boolean;
}

/** What the beds suggest by the PHC's bands; a person records the category on the licence (POST /establishment/changes with a profile). */
export interface CategorySuggestionOut {
  /** Null: no inpatient bed is set up (a clinic, or a hospital whose beds are not set up yet) */
  category: "I" | "IIA" | "IIB" | "IIC" | null;
  category_label: string | null;
  /** The beds set up: the active beds of the active wards, emergency wards left out */
  beds: number;
  /** The beds in use: those set up, less the ones out of service */
  operational: number;
  /** The beds set up but out of service now (a temporary closure) */
  out_of_service: number;
  /** Whether Haspataal holds the suggested category's framework (all five since 2026-10-14) */
  supported: boolean;
  /** One sentence to show next to the suggestion */
  note: string;
  wards: CountedWardOut[];
}

export interface CountedWardOut {
  ward_id: number;
  code: string;
  name: string;
  ward_type: "General" | "Private" | "SemiPrivate" | "ICU" | "CCU" | "NICU" | "Surgical" | "Pediatric" | "Maternity" | "Emergency" | "Isolation" | "Other";
  /** Its active beds */
  beds: number;
  /** Of those, the beds out of service now (a temporary closure) */
  out_of_service: number;
  /** False for emergency wards: ER observation beds are not indoor strength */
  counted: boolean;
}

export interface StandardOut {
  category: "Clinic" | "IIC" | "IIB" | "IIA" | "I";
  label: string;
  /** The PHC document the indicators come from */
  edition: string;
  indicators: number;
}

export interface MyPreferencesOut {
  theme: "Light" | "DarkHighContrast";
  language: "en" | "ur";
  ui_scale_pct: number;
  /** How a set of documents (the MSDS inspection pack) downloads: Separate = a button per document, one PDF each; Combined = one button, one PDF with all of them */
  pdf_download: "Separate" | "Combined";
  /** Anything else the frontend stores for this user */
  extra: Record<string, unknown>;
  /** Null until the user saves preferences for the first time */
  updated_at: string | null;
}

export interface RegisterPartsOut {
  date_from: string;
  date_to: string;
  /** Visits and admissions in the period */
  entries: number;
  /** At most this many entries per part */
  part_rows: number;
  parts: RegisterPartOut[];
}

export interface RegisterPartOut {
  part: number;
  entries: number;
  /** The first entry's time */
  first_at: string;
  last_at: string;
  pdf_url: string;
}

/** A person the search found, always as their master record (merged profiles are never hits of their own). */
export interface PatientSearchHitOut {
  patient_id: number;
  /** The newest Patient Photo of the merge chain, for the identity check; null when none was taken (it is optional). GET /patient-documents/{document_id}/download */
  photo_document_id: number | null;
  mrn: string;
  registration_type: "Regular" | "LabOnly" | "TraumaTemp" | "Merged";
  full_name: string;
  father_or_husband_name: string | null;
  gender: "male" | "female" | "other" | "unknown" | null;
  dob: string | null;
  age_years: number | null;
  /** When age_years was recorded (the age grows from that date) */
  age_recorded_on: string | null;
  mobile: string | null;
  cnic: string | null;
  /** The Universal Patient Medical Record Number when one was recorded (optional) */
  upmrn: string | null;
  address: string | null;
  emergency_contact_name: string | null;
  emergency_contact_phone: string | null;
  blood_group: "A+" | "A-" | "B+" | "B-" | "AB+" | "AB-" | "O+" | "O-" | "Unknown" | null;
  allergies: string | null;
  billing_category: "Cash" | "Panel";
  panel_id: number | null;
  panel_name: string | null;
  panel_member_no: string | null;
  /** Unknown-trauma label, e.g. "Unknown Male 3" */
  temp_identifier: string | null;
  merged_into_id: number | null;
  linked_employee_id: number | null;
  is_deceased: boolean;
  /** The death record (GET /deaths/{death_id}) when the death is recorded */
  death_id: number | null;
  death_at: string | null;
  /** Medico-legal case numbers of this person: show a MEDICO-LEGAL banner when not empty (MSDS 154: the record is clearly so marked) */
  mlc_numbers: string[];
  created_at: string;
  row_version: number;
  outstanding: OutstandingBannerOut;
  /** The profile merged into this record that the search matched when this record itself did not (an old slip's MRN, a trauma label such as "Unknown Male 3", a duplicate's name or numbers): say "Found by MRN-…, merged into this record". Null when this record matched */
  matched_merged_profile: MergedProfileOut | null;
}

/** Outstanding dues of the patient's whole merge chain (workflow sections 1.2 and 1.9). */
export interface OutstandingBannerOut {
  has_outstanding_ar: boolean;
  outstanding_ar_balance: number;
  /** True: reception blocks a new OPD slip unless ER bypass or an override */
  ar_block_applies: boolean;
  /** Show it prominently, e.g. "OUTSTANDING BALANCE: RS. 2,500" */
  banner_text: string | null;
}

/** Another record of the same person, merged into this one (e.g. a trauma registration). */
export interface MergedProfileOut {
  patient_id: number;
  mrn: string;
  full_name: string;
  registration_type: "Regular" | "LabOnly" | "TraumaTemp" | "Merged";
  temp_identifier: string | null;
}

/** The inspection documents of the category, with their readiness and download links — GET /api/v1/msds/inspection-pack (who may call: holders of msds.view or msds.inspect). */
export function inspectionPack(query?: { category?: "Clinic" | "IIC" | "IIB" | "IIA" | "I" | null; date_from?: string | null; date_to?: string | null }): Promise<InspectionPackOut> {
  return api<InspectionPackOut>("GET", withQuery(`/msds/inspection-pack`, query), undefined);
}

/** One inspection document (PDF) — GET /api/v1/msds/inspection-pack/documents/{key}/pdf (who may call: holders of msds.view or msds.inspect). */
export function documentPdfMsdsInspectionPackDocuments(key: string, query?: { category?: "Clinic" | "IIC" | "IIB" | "IIA" | "I" | null; date_from?: string | null; date_to?: string | null }): Promise<unknown> {
  return api<unknown>("GET", withQuery(`/msds/inspection-pack/documents/${key}/pdf`, query), undefined);
}

/** Build the whole inspection pack as one PDF, in the background — POST /api/v1/msds/inspection-pack/exports (who may call: holders of msds.view or msds.inspect). */
export function requestPackExport(body: PackExportIn): Promise<MsdsPackExportOut> {
  return api<MsdsPackExportOut>("POST", `/msds/inspection-pack/exports`, body, { idempotent: true });
}

/** A combined inspection pack being built: Queued, Ready or Failed — GET /api/v1/msds/inspection-pack/exports/{export_id} (who may call: holders of msds.view or msds.inspect). */
export function getPackExport(export_id: number): Promise<MsdsPackExportOut> {
  return api<MsdsPackExportOut>("GET", `/msds/inspection-pack/exports/${export_id}`, undefined);
}

/** The combined inspection pack (PDF), once Ready — GET /api/v1/msds/inspection-pack/exports/{export_id}/pdf (who may call: holders of msds.view or msds.inspect). */
export function packExportPdf(export_id: number): Promise<unknown> {
  return api<unknown>("GET", `/msds/inspection-pack/exports/${export_id}/pdf`, undefined);
}

/** The PHC category: as confirmed, and what the beds suggest — GET /api/v1/msds/profile (who may call: holders of msds.view or establishment.manage or msds.inspect). */
export function getProfile(): Promise<MsdsProfileOut> {
  return api<MsdsProfileOut>("GET", `/msds/profile`, undefined);
}

/** My preferences (theme, language, UI scale, PDF download) — GET /api/v1/settings/me (who may call: any logged-in user, for their own account (also before a forced password change where allowed)). */
export function getPrefs(): Promise<MyPreferencesOut> {
  return api<MyPreferencesOut>("GET", `/settings/me`, undefined);
}

/** The patient's record register of a period: its size and its parts — GET /api/v1/msds/patient-register (who may call: holders of msds.view). */
export function registerParts(query: { date_from: string; date_to: string }): Promise<RegisterPartsOut> {
  return api<RegisterPartsOut>("GET", withQuery(`/msds/patient-register`, query), undefined);
}

/** One part of the patient's record register (PDF) — GET /api/v1/msds/patient-register/pdf (who may call: holders of msds.view). */
export function registerPdfMsdsPatient(query: { date_from: string; date_to: string; part?: number }): Promise<unknown> {
  return api<unknown>("GET", withQuery(`/msds/patient-register/pdf`, query), undefined);
}

/** The records of selected patients for a period (PDF) — GET /api/v1/msds/selected-records/pdf (who may call: holders of msds.view). */
export function selectedRecords(query: { date_from: string; date_to: string; patient_id: number[] }): Promise<unknown> {
  return api<unknown>("GET", withQuery(`/msds/selected-records/pdf`, query), undefined);
}

/** Returning-patient lookup by name / phone / CNIC / UPMRN / MRN — GET /api/v1/patients/search (who may call: holders of patient.search). */
export function searchPatients(query: { q: string; limit?: number }): Promise<PatientSearchHitOut[]> {
  return api<PatientSearchHitOut[]>("GET", withQuery(`/patients/search`, query), undefined);
}
